cat > src/unpipe-all.js <<'EOF'
/**
 * Detach a readable stream from every destination it is piped to.
 *
 * Uses the native `readable.unpipe()` (no argument = all destinations).
 * The stream is left paused so no data is lost after detaching.
 *
 * @param {import('node:stream').Readable} stream
 * @returns {import('node:stream').Readable} the same stream
 */
export function unpipeAll(stream) {
  if (!stream || typeof stream.unpipe !== 'function') {
    throw new TypeError('argument stream must be a readable stream');
  }
  stream.unpipe();
  if (typeof stream.pause === 'function') stream.pause();
  return stream;
}
EOF
cat > src/server.js <<'EOF'
import http from 'node:http';
import { pathToFileURL } from 'node:url';
import { unpipeAll } from './unpipe-all.js';

export function createServer() {
  return http.createServer((req, res) => {
    if (req.method === 'POST' && req.url === '/echo') {
      // Stream the request body back to the client.
      req.pipe(res);

      // If either side goes away early, detach the request from all destinations.
      const cleanup = () => {
        unpipeAll(req);
        req.resume(); // drain remaining input so the socket can be reused/closed
      };
      req.on('error', cleanup);
      res.on('close', () => {
        if (!res.writableFinished) cleanup();
      });
      return;
    }

    if (req.method === 'GET' && req.url === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
      return;
    }

    res.writeHead(404, { 'content-type': 'text/plain' });
    res.end('Not Found');
  });
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT) || 3000;
  createServer().listen(port, () => {
    console.log(`Server listening on http://localhost:${port}`);
  });
}
EOF
cat > test/unpipe-all.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { PassThrough, Readable } from 'node:stream';
import { unpipeAll } from '../src/unpipe-all.js';

test('detaches all destinations', () => {
  const src = new PassThrough();
  const a = new PassThrough();
  const b = new PassThrough();
  src.pipe(a);
  src.pipe(b);
  assert.equal(src.listenerCount('data'), 1);
  assert.equal(src._readableState.pipes.length, 2);

  unpipeAll(src);

  assert.equal(src._readableState.pipes.length, 0);
  assert.equal(src.isPaused(), true);
});

test('emits unpipe on every destination', () => {
  const src = new PassThrough();
  const dests = [new PassThrough(), new PassThrough(), new PassThrough()];
  let count = 0;
  for (const d of dests) {
    d.on('unpipe', (s) => { assert.equal(s, src); count++; });
    src.pipe(d);
  }
  unpipeAll(src);
  assert.equal(count, 3);
});

test('no data flows to destinations after unpipe', async () => {
  const src = new PassThrough();
  const dest = new PassThrough();
  const received = [];
  dest.on('data', (c) => received.push(c.toString()));
  src.pipe(dest);
  src.write('before');
  await new Promise((r) => setImmediate(r));
  unpipeAll(src);
  src.write('after');
  await new Promise((r) => setImmediate(r));
  assert.deepEqual(received, ['before']);
  assert.equal(src.read().toString(), 'after'); // data retained, not lost
});

test('is safe on a stream with no destinations', () => {
  const src = Readable.from([]);
  assert.doesNotThrow(() => unpipeAll(src));
});

test('rejects non-streams', () => {
  assert.throws(() => unpipeAll(null), TypeError);
  assert.throws(() => unpipeAll({}), TypeError);
});
EOF
cat > test/server.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from '../src/server.js';

let server, base;
before(async () => {
  server = createServer();
  await new Promise((r) => server.listen(0, r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server.close());

test('GET /health', async () => {
  const res = await fetch(`${base}/health`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { status: 'ok' });
});

test('POST /echo streams body back', async () => {
  const res = await fetch(`${base}/echo`, { method: 'POST', body: 'hello stream' });
  assert.equal(await res.text(), 'hello stream');
});

test('unknown route returns 404', async () => {
  const res = await fetch(`${base}/nope`);
  assert.equal(res.status, 404);
});
EOF
